package io.github.diodeme.ji.artifact;

import io.github.diodeme.ji.error.ErrorCode;
import io.github.diodeme.ji.error.JiError;
import io.github.diodeme.ji.error.JiException;
import java.util.Map;
import java.util.Optional;
import java.util.OptionalLong;

/** Factory for versioned public artifact errors. */
public final class ArtifactErrors {
    private ArtifactErrors() {}

    public static JiException invalidUpload(String reason) {
        return error(ErrorCode.ARTIFACT_INVALID_UPLOAD, Map.of("reason", reason));
    }

    public static JiException quotaExceeded(long currentBytes, long requestedBytes, long quotaBytes) {
        return error(ErrorCode.ARTIFACT_QUOTA_EXCEEDED, Map.of(
                "currentBytes", Long.toString(currentBytes),
                "requestedBytes", Long.toString(requestedBytes),
                "quotaBytes", Long.toString(quotaBytes)));
    }

    public static JiException hashMismatch(String expectedSha256, String actualSha256) {
        return error(ErrorCode.ARTIFACT_HASH_MISMATCH, Map.of(
                "expectedSha256", expectedSha256, "actualSha256", actualSha256));
    }

    public static JiException notFound(ArtifactId artifactId) {
        return error(ErrorCode.ARTIFACT_NOT_FOUND, Map.of("artifactId", artifactId.value()));
    }

    public static JiException corrupt(ArtifactId artifactId) {
        return error(ErrorCode.ARTIFACT_CORRUPT, Map.of("artifactId", artifactId.value()));
    }

    public static JiException unavailable(Throwable cause) {
        return new JiException(contract(ErrorCode.ARTIFACT_STORE_UNAVAILABLE, Map.of()), cause);
    }

    public static JiException workspaceSourceForbidden(String sessionId) {
        return error(ErrorCode.ARTIFACT_WORKSPACE_SOURCE_FORBIDDEN, Map.of("sessionId", sessionId));
    }

    private static JiException error(ErrorCode code, Map<String, String> parameters) {
        return new JiException(contract(code, parameters));
    }

    private static JiError contract(ErrorCode code, Map<String, String> parameters) {
        return new JiError(code, parameters, Optional.empty(), Optional.empty(), OptionalLong.empty());
    }
}
